     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.temporal.ChronoUnit;
     6	
     7	public final class Pricing {
     8	    private Pricing() {
     9	    }
    10	
    11	    /** Alta temporada: de 15 de dezembro ao fim de fevereiro, e julho inteiro. */
    12	    public static boolean isHighSeason(LocalDate night) {
    13	        int month = night.getMonthValue();
    14	        return month == 1 || month == 2 || month == 7 || (month == 12 && night.getDayOfMonth() >= 15);
    15	    }
    16	
    17	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    18	        return isHighSeason(night) ? Money.times(room.nightlyRate(), "1.20") : room.nightlyRate();
    19	    }
    20	
    21	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    22	        BigDecimal subtotal = Money.ZERO;
    23	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    24	            subtotal = Money.round(subtotal.add(nightPrice(room, night)));
    25	        }
    26	        BigDecimal discount = plan.discountOn(subtotal);
    27	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    28	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    29	    }
    30	
    31	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    32	    }
    33	}
