    15	        Identity identity,
    16	        LocalDate checkIn,
    17	        LocalDate checkOut,
    18	        int guests,
    19	        RatePlan ratePlan,
    20	        int nights,
    21	        BigDecimal subtotal,
    22	        BigDecimal discount,
    23	        BigDecimal total,
    24	        ReservationStatus status,
