    27	
    28	    public Reservation withId(long newId) {
    29	        return new Reservation(newId, roomNumber, guestName, guestEmail, identity, checkIn, checkOut, guests,
    30	                ratePlan, nights, subtotal, discount, total, status, amountPaid, refund);
    31	    }
    32	
    33	    public Reservation confirm() {
    34	        return transition(Set.of(PENDING), CONFIRMED, total, refund);
    35	    }
    36	
    37	    public Reservation startStay() {
    38	        return transition(Set.of(CONFIRMED), CHECKED_IN, amountPaid, refund);
    39	    }
    40	
    41	    public Reservation endStay() {
    42	        return transition(Set.of(CHECKED_IN), CHECKED_OUT, amountPaid, refund);
    43	    }
    44	
    45	    public Reservation cancel() {
    46	        return transition(Set.of(PENDING, CONFIRMED), CANCELLED, amountPaid, ratePlan.refundFor(amountPaid));
    47	    }
    48	
    49	    public boolean isPaid() {
    50	        return PAID.contains(status);
    51	    }
    52	
    53	    /** O que a pousada guarda: o que foi pago menos o que foi devolvido. */
