    58	    private Reservation transition(Set<ReservationStatus> allowedFrom, ReservationStatus to,
    59	                                   BigDecimal paid, BigDecimal newRefund) {
    60	        if (!allowedFrom.contains(status)) {
    61	            throw ApiException.notAllowed("Reserva " + id + " está " + status + " e não pode passar para " + to);
    62	        }
    63	        return new Reservation(id, roomNumber, guestName, guestEmail, identity, checkIn, checkOut, guests,
    64	                ratePlan, nights, subtotal, discount, total, to, paid, newRefund);
