     1	package pousada.document;
     2	
     3	import java.math.BigDecimal;
     4	import java.util.ArrayList;
     5	import java.util.List;
     6	import java.util.Map;
     7	
     8	/**
     9	 * Um tipo de documento da reserva. A sequência de linhas é escrita aqui, uma vez só;
    10	 * cada tipo informa os campos de identificação, o título, o idioma e o que muda no texto.
    11	 * Para um tipo novo: criar a subclasse e acrescentá-la em {@link DocumentTypes}.
    12	 */
    13	public abstract class DocumentType {
    14	    /** Código guardado no banco. */
    15	    public abstract String code();
    16	
    17	    /** Campos do corpo da reserva que identificam o hóspede neste tipo; todos são obrigatórios. */
    18	    public abstract List<String> fields();
    19	
    20	    public abstract String title();
    21	
    22	    protected abstract Language language();
    23	
    24	    /** Linhas de identificação, entre o título e o quarto. */
    25	    protected abstract List<String> identityLines(String guestName, Map<String, String> identity);
    26	
    27	    /** Linhas depois do total. */
    28	    protected List<String> closingLines(DocumentData data) {
    29	        return List.of();
    30	    }
    31	
    32	    public final String render(DocumentData data, Map<String, String> identity) {
    33	        Language lang = language();
    34	        List<String> lines = new ArrayList<>();
    35	        lines.add(title() + " " + lang.number + " " + data.reservationId());
    36	        lines.addAll(identityLines(data.guestName(), identity));
    37	        lines.add(lang.room + ": " + data.roomNumber() + " (" + data.roomType() + ")");
    38	        lines.add(lang.checkIn + ": " + lang.date(data.checkIn()) + " | "
    39	                + lang.checkOut + ": " + lang.date(data.checkOut()) + " | " + lang.nights(data.nights()));
    40	        lines.add(lang.subtotal + ": " + lang.money(data.subtotal()));
    41	        if (data.discount().compareTo(BigDecimal.ZERO) > 0) {
    42	            lines.add(lang.discount + ": " + lang.money(data.discount()));
    43	        }
    44	        lines.add(lang.total + ": " + lang.money(data.total()));
    45	        lines.addAll(closingLines(data));
    46	        return String.join("\n", lines);
    47	    }
    48	}
