     1	package pousada.document;
     2	
     3	import java.util.LinkedHashMap;
     4	import java.util.LinkedHashSet;
     5	import java.util.List;
     6	import java.util.Map;
     7	import java.util.Set;
     8	import pousada.ApiException;
     9	import pousada.domain.Identity;
    10	
    11	/** Os tipos de documento que existem. Um tipo novo entra só na lista abaixo. */
    12	public final class DocumentTypes {
    13	    private static final List<DocumentType> ALL = List.of(
    14	            new CpfReceipt(),
    15	            new CompanyInvoice(),
    16	            new PassportReceipt());
    17	
    18	    private DocumentTypes() {
    19	    }
    20	
    21	    /** Todos os campos de identificação de todos os tipos, na ordem de declaração. */
    22	    public static Set<String> allFields() {
    23	        Set<String> fields = new LinkedHashSet<>();
    24	        ALL.forEach(type -> fields.addAll(type.fields()));
    25	        return fields;
    26	    }
    27	
    28	    public static DocumentType byCode(String code) {
    29	        return ALL.stream().filter(type -> type.code().equals(code)).findFirst()
    30	                .orElseThrow(() -> new IllegalStateException("Tipo de documento desconhecido: " + code));
    31	    }
    32	
    33	    /**
    34	     * Descobre como o hóspede se identifica. {@code given} traz cada campo de identificação
    35	     * (null ou vazio quando não veio); tem que haver exatamente um tipo, com todos os seus campos.
    36	     */
    37	    public static Identity resolve(Map<String, String> given) {
    38	        List<DocumentType> used = ALL.stream()
    39	                .filter(type -> type.fields().stream().anyMatch(field -> present(given.get(field))))
    40	                .toList();
    41	        if (used.size() != 1) {
    42	            throw ApiException.invalid("Informe a identificação de um único jeito: guestCpf, "
    43	                    + "companyCnpj com companyName, ou guestPassport com guestCountry");
    44	        }
    45	        DocumentType type = used.get(0);
    46	        Map<String, String> values = new LinkedHashMap<>();
    47	        for (String field : type.fields()) {
    48	            if (!present(given.get(field))) {
    49	                throw ApiException.invalid("Campo obrigatório ausente: " + field);
    50	            }
    51	            values.put(field, given.get(field).trim());
    52	        }
    53	        return new Identity(type.code(), values);
    54	    }
    55	
    56	    private static boolean present(String value) {
    57	        return value != null && !value.isBlank();
    58	    }
    59	}
