     1	package pousada.persistence;
     2	
     3	import java.sql.Connection;
     4	import java.sql.DriverManager;
     5	import java.sql.SQLException;
     6	import java.sql.Statement;
     7	
     8	public final class Database {
     9	    @FunctionalInterface
    10	    public interface Work<T> {
    11	        T run(Connection connection) throws SQLException;
    12	    }
    13	
    14	    private final String url;
    15	    private final String user;
    16	    private final String password;
    17	
    18	    public Database(String url, String user, String password) {
    19	        this.url = url;
    20	        this.user = user;
    21	        this.password = password;
    22	    }
    23	
    24	    /** Executa o trabalho numa transação: confirma se terminar, desfaz se falhar. */
    25	    public <T> T tx(Work<T> work) {
    26	        try (Connection connection = DriverManager.getConnection(url, user, password)) {
    27	            connection.setAutoCommit(false);
    28	            try {
    29	                T result = work.run(connection);
    30	                connection.commit();
    31	                return result;
    32	            } catch (SQLException | RuntimeException e) {
    33	                connection.rollback();
    34	                throw e;
    35	            }
    36	        } catch (SQLException e) {
    37	            throw new IllegalStateException("Erro no banco de dados: " + e.getMessage(), e);
    38	        }
    39	    }
    40	
    41	    /** Cria o que o sistema precisa, esperando o banco ficar disponível se for preciso. */
    42	    public void createSchema() {
    43	        for (int attempt = 1; ; attempt++) {
    44	            try {
    45	                tx(connection -> {
    46	                    try (Statement st = connection.createStatement()) {
    47	                        st.execute("SELECT pg_advisory_xact_lock(1)");
    48	                        st.execute("""
    49	                                CREATE TABLE IF NOT EXISTS reservations (
    50	                                  id BIGSERIAL PRIMARY KEY,
    51	                                  room_number INT NOT NULL,
    52	                                  guest_name TEXT NOT NULL,
